import { inputGroupAddonVariants, type InputGroupAddonVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"div">, InputGroupAddonVariants {}

<const/{ align = "inline-start", class: className, content, ...rest }=input/>

<div
  role="group"
  data-slot="input-group-addon"
  data-align=align
  ...rest
  onClick(event, target: HTMLElement) {
    if ((event.target as HTMLElement).closest("button")) return;
    // event.currentTarget is unsupported in Marko's delegated events —
    // the handler's 2nd argument is the element the handler is bound to.
    target.parentElement
      ?.querySelector<HTMLElement>("input")
      ?.focus();
  }
  class=cn(inputGroupAddonVariants({ align }), className)
>
  <${content}/>
</div>

import Button from "../button/button.marko";
import type { ButtonVariants } from "../button/variants.ts";
import { inputGroupButtonVariants, type InputGroupButtonVariants } from "./variants.ts";
import { cn } from "../../../lib/utils.ts";

export interface Input
  extends Omit<Marko.Input<"button">, "size">,
    Pick<ButtonVariants, "variant">,
    InputGroupButtonVariants {}

<const/{ variant, size = "xs", class: className, content, ...rest }=input/>

<Button
  type=input.type ?? "button"
  data-size=size
  variant=variant ?? "ghost"
  ...rest
  class=cn(inputGroupButtonVariants({ size }), className)
>
  <${content}/>
</Button>

import InputField from "../input/input.marko";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"input"> {}

<const/{ class: className, ...rest }=input/>

<InputField
  data-slot="input-group-control"
  ...rest
  class=cn("rounded-none border-0 bg-transparent shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent flex-1", className)
/>

import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"span"> {}

<const/{ class: className, content, ...rest }=input/>

<span
  ...rest
  class=cn(
    "text-muted-foreground gap-2 text-sm [&_svg:not([class*='size-'])]:size-4 flex items-center [&_svg]:pointer-events-none",
    className,
  )
>
  <${content}/>
</span>

import TextareaField from "../textarea/textarea.marko";
import { cn } from "../../../lib/utils.ts";

export interface Input extends Marko.Input<"textarea"> {}

<const/{ class: className, ...rest }=input/>

<TextareaField
  data-slot="input-group-control"
  ...rest
  class=cn("rounded-none border-0 bg-transparent py-2.5 shadow-none ring-0 focus-visible:ring-0 aria-invalid:ring-0 dark:bg-transparent flex-1 resize-none", className)
/>

import { cva, type VariantProps } from "class-variance-authority";

export const inputGroupAddonVariants = cva(
  "text-muted-foreground **:data-[slot=kbd]:bg-muted-foreground/10 h-auto gap-2 py-2 text-sm font-medium group-data-[disabled=true]/input-group:opacity-50 **:data-[slot=kbd]:rounded-3xl **:data-[slot=kbd]:px-1.5 [&>svg:not([class*='size-'])]:size-4 flex cursor-text items-center justify-center select-none",
  {
    variants: {
      align: {
        "inline-start": "pl-3 has-[>button]:-ml-1 has-[>kbd]:-ml-1 order-first",
        "inline-end": "pr-3 has-[>button]:-mr-1 has-[>kbd]:-mr-1 order-last",
        "block-start":
          "px-3 pt-3 group-has-[>input]/input-group:pt-3.5 [.border-b]:pb-3.5 order-first w-full justify-start",
        "block-end":
          "px-3 pb-3 group-has-[>input]/input-group:pb-3.5 [.border-t]:pt-3.5 order-last w-full justify-start",
      },
    },
    defaultVariants: {
      align: "inline-start",
    },
  },
);

export type InputGroupAddonVariants = VariantProps<typeof inputGroupAddonVariants>;

export const inputGroupButtonVariants = cva(
  "gap-2 rounded-4xl text-sm flex items-center shadow-none",
  {
    variants: {
      size: {
        xs: "h-6 gap-1 rounded-xl px-1.5 [&>svg:not([class*='size-'])]:size-3.5",
        sm: "",
        "icon-xs": "size-6 rounded-xl p-0 has-[>svg]:p-0",
        "icon-sm": "size-8 p-0 has-[>svg]:p-0",
      },
    },
    defaultVariants: {
      size: "xs",
    },
  },
);

export type InputGroupButtonVariants = VariantProps<typeof inputGroupButtonVariants>;
